<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'

const items = ref<any[]>([]); const clients = ref<any[]>([]); const agencyPositions = ref<any[]>([]); const regions = ref<any[]>([]); const payrollRates = ref<any[]>([]); const billingRates = ref<any[]>([])
const form = ref<any>({ ClientID: '', AgencyPositionID: '', PayrollRateID: '', BillingRateID: '', Status: 'Active' }); const editing = ref<any>(null); const open = ref(false); const busy = ref(false); const loading = ref(true); const error = ref(''); const inlinePayroll = ref(false); const inlineBilling = ref(false); const inlineRegionID = ref(''); const inlinePayrollRegularRate = ref(0); const inlineBillingRegularRate = ref(0)
const filteredPayroll = computed(() => payrollRates.value.filter((rate) => Number(rate.AgencyPositionID) === Number(form.value.AgencyPositionID) && rate.Status === 'Active'))
const filteredBilling = computed(() => billingRates.value.filter((rate) => Number(rate.AgencyPositionID) === Number(form.value.AgencyPositionID) && rate.Status === 'Active'))
function label(rate: any) { return `${rate.RegionName || 'All regions'} — ₱${Number(rate.RegularRate || 0).toFixed(2)} (${rate.EffectiveDate || 'no date'})` }
function reset(item: any = null) { editing.value = item; form.value = { ClientID: item?.ClientID ?? '', AgencyPositionID: item?.AgencyPositionID ?? '', PayrollRateID: item?.PayrollRateID ?? '', BillingRateID: item?.BillingRateID ?? '', Status: item?.Status ?? 'Active' }; inlinePayroll.value = false; inlineBilling.value = false; inlineRegionID.value = item?.RegionID ?? ''; inlinePayrollRegularRate.value = 0; inlineBillingRegularRate.value = 0; error.value = '' }
async function load() { loading.value = true; try { const response: any = await $fetch('/api/rates/client-rate'); items.value = response.items || []; clients.value = response.clients || []; agencyPositions.value = response.agencyPositions || []; regions.value = response.regions || []; payrollRates.value = response.payrollRates || []; billingRates.value = response.billingRates || [] } catch (e: any) { error.value = e.data?.statusMessage || 'Unable to load client rates.' } finally { loading.value = false } }
async function save() { busy.value = true; error.value = ''; try { const body: any = { ...form.value }; if (!editing.value && inlinePayroll.value) body.inlinePayrollRate = { RegionID: inlineRegionID.value, RegularRate: inlinePayrollRegularRate.value }; if (!editing.value && inlineBilling.value) body.inlineBillingRate = { RegionID: inlineRegionID.value, RegularRate: inlineBillingRegularRate.value }; await $fetch('/api/rates/client-rate', { method: editing.value ? 'PUT' : 'POST', body: editing.value ? { id: editing.value.ClientRateID, ...body } : body }); open.value = false; await load() } catch (e: any) { error.value = e.data?.statusMessage || 'Unable to save client rate.' } finally { busy.value = false } }
async function deactivate(item: any) { if (!confirm('Mark this client rate as inactive?')) return; try { await $fetch('/api/rates/client-rate', { method: 'DELETE', body: { id: item.ClientRateID } }); await load() } catch (e: any) { error.value = e.data?.statusMessage || 'Unable to deactivate client rate.' } }
onMounted(load)
</script>
<template><main class="client-rate-page"><header><div><p>RATES</p><h1>Client Rates</h1></div><button class="primary" @click="reset(); open = true">+ Link rates</button></header><p v-if="error" class="error">{{ error }}</p><div class="table-wrap"><table><thead><tr><th>Client</th><th>Agency position</th><th>Region</th><th>Payroll regular</th><th>Billing regular</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="7">Loading…</td></tr><tr v-else-if="!items.length"><td colspan="7">No client rates found.</td></tr><tr v-for="item in items" :key="item.ClientRateID"><td>{{ item.ClientName }}</td><td>{{ item.AgencyName }} — {{ item.PositionName }}</td><td>{{ item.RegionName || 'All regions' }}</td><td>₱{{ Number(item.PayrollRegularRate || 0).toFixed(2) }}</td><td>₱{{ Number(item.BillingRegularRate || 0).toFixed(2) }}</td><td>{{ item.Status }}</td><td><button @click="reset(item); open = true">Edit</button><button :disabled="item.Status === 'Inactive'" @click="deactivate(item)">Deactivate</button></td></tr></tbody></table></div><Teleport to="body"><div v-if="open" class="backdrop" @click.self="!busy && (open = false)"><form class="modal" @submit.prevent="save"><button class="close" type="button" @click="open = false">×</button><h2>{{ editing ? 'Edit client rate' : 'Link client rates' }}</h2><label>Client<select v-model="form.ClientID" required><option value="">Select client</option><option v-for="client in clients" :key="client.ClientID" :value="client.ClientID">{{ client.ClientName }}</option></select></label><label>Agency position<select v-model="form.AgencyPositionID" required @change="form.PayrollRateID = ''; form.BillingRateID = ''"><option value="">Select agency position</option><option v-for="position in agencyPositions" :key="position.AgencyPositionID" :value="position.AgencyPositionID">{{ position.AgencyName }} — {{ position.PositionName }}</option></select></label><template v-if="form.AgencyPositionID"><label>Payroll rate<select v-model="form.PayrollRateID" :disabled="inlinePayroll" :required="!inlinePayroll"><option value="">Select existing payroll rate</option><option v-for="rate in filteredPayroll" :key="rate.PayrollRateID" :value="rate.PayrollRateID">{{ label(rate) }}</option></select></label><label class="toggle"><input v-model="inlinePayroll" type="checkbox" /> Create payroll rate inline</label><label v-if="inlinePayroll">Payroll regular rate<input v-model="inlinePayrollRegularRate" type="number" min="0" step="0.01" required /></label><label>Billing rate<select v-model="form.BillingRateID" :disabled="inlineBilling" :required="!inlineBilling"><option value="">Select existing billing rate</option><option v-for="rate in filteredBilling" :key="rate.BillingRateID" :value="rate.BillingRateID">{{ label(rate) }}</option></select></label><label class="toggle"><input v-model="inlineBilling" type="checkbox" /> Create billing rate inline</label><label v-if="inlineBilling">Billing regular rate<input v-model="inlineBillingRegularRate" type="number" min="0" step="0.01" required /></label><label v-if="inlinePayroll || inlineBilling">Region for inline rate<select v-model="inlineRegionID"><option value="">All regions</option><option v-for="region in regions" :key="region.RegionID" :value="region.RegionID">{{ region.RegionCode }} — {{ region.RegionName }}</option></select></label></template><label>Status<select v-model="form.Status"><option>Active</option><option>Inactive</option></select></label><p v-if="error" class="error">{{ error }}</p><footer><button type="button" @click="open = false">Cancel</button><button class="primary" :disabled="busy">{{ busy ? 'Saving…' : 'Save link' }}</button></footer></form></div></Teleport></main></template>
<style scoped>
.client-rate-page{padding:32px;max-width:1200px;margin:auto;color:#172033;font-family:Inter,system-ui,sans-serif}.client-rate-page header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.client-rate-page header p{margin:0;color:#5271a5;font-size:.75rem;font-weight:800;letter-spacing:.08em}.client-rate-page h1{margin:3px 0 0;font-size:1.7rem}.primary{border:0;border-radius:8px;background:#2563eb;color:#fff;padding:10px 15px;font-weight:700;cursor:pointer}.table-wrap{overflow:auto;border:1px solid #dfe5ef;border-radius:10px}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:13px 14px;text-align:left;border-bottom:1px solid #edf1f6;font-size:.88rem;white-space:nowrap}th{background:#f8fafc;color:#526174;font-size:.75rem;text-transform:uppercase}td button,footer button{border:1px solid #cfd8e6;background:#fff;border-radius:6px;padding:6px 9px;margin-right:6px;cursor:pointer}.error{color:#b42318}.backdrop{position:fixed;inset:0;z-index:300;background:rgba(15,23,42,.58);display:grid;place-items:center;padding:16px}.modal{position:relative;width:min(100%,560px);max-height:90vh;overflow:auto;background:#fff;border-radius:12px;padding:26px;display:grid;gap:12px}.modal h2{margin:0}.modal label{display:grid;gap:5px;font-size:.8rem;font-weight:700;color:#475569}.modal input,.modal select{min-height:40px;border:1px solid #cfd8e6;border-radius:7px;padding:8px;font:inherit}.toggle{display:flex!important;grid-template-columns:auto 1fr;align-items:center;gap:8px}.close{position:absolute;right:12px;top:10px;border:0;background:transparent;font-size:1.5rem;cursor:pointer}.modal footer{display:flex;justify-content:flex-end;margin-top:6px}
</style>
